<script setup lang="ts">import {computed} from 'vue';import {fixed} from '../utils/format';const props=defineProps<{result:any}>();const ratio=computed(()=>Number(props.result.variance_ratio_analysis??props.result.deming?.lambda));const inputRatio=computed(()=>props.result.variance_ratio_input);const adjusted=computed(()=>inputRatio.value!==undefined&&Math.abs(inputRatio.value-ratio.value)>1e-15)</script><template><div class="metric-strip"><div><small>Deming 斜率 / 截距</small><strong>{{fixed(result.deming.slope,4)}} <em>/ {{fixed(result.deming.intercept)}}</em></strong><span>λ={{ratio}}<template v-if="adjusted">（原单位输入 {{inputRatio}}，按换算调整）</template></span></div><div><small>差值平均偏倚 y−x</small><strong>{{fixed(result.agreement.bias)}} <em>{{result.unit}}</em></strong><span>SD {{fixed(result.agreement.sample_sd)}} · ddof=1</span></div><div><small>一致性界限</small><strong>{{fixed(result.agreement.loa_low,2)}} <em>~ {{fixed(result.agreement.loa_high,2)}}</em></strong><span>不是置信区间</span></div></div></template>
